/// <reference lib="webworker" />
declare const self: ServiceWorkerGlobalScope;

import { precacheAndRoute, cleanupOutdatedCaches } from 'workbox-precaching';
import { registerRoute } from 'workbox-routing';
import { CacheFirst, StaleWhileRevalidate, NetworkFirst } from 'workbox-strategies';
import { ExpirationPlugin } from 'workbox-expiration';

// Clean old precached assets
cleanupOutdatedCaches();

// Precache all assets generated by Vite
precacheAndRoute(self.__WB_MANIFEST || []);

// 1. Cache Campus Pack Assets (PMTiles, Floorplan SVGs, Buildings JSON)
registerRoute(
  ({ url }) => url.pathname.startsWith('/packs/'),
  new CacheFirst({
    cacheName: 'quadrant-campus-packs-v1',
    plugins: [
      new ExpirationPlugin({
        maxEntries: 200,
        maxAgeSeconds: 30 * 24 * 60 * 60 // 30 Days
      })
    ]
  })
);

// 2. Leaflet and map tile dependencies
registerRoute(
  ({ url }) => url.origin.includes('unpkg.com') || url.pathname.endsWith('.pmtiles'),
  new CacheFirst({
    cacheName: 'quadrant-map-assets-v1',
    plugins: [
      new ExpirationPlugin({
        maxEntries: 100,
        maxAgeSeconds: 60 * 24 * 60 * 60 // 60 Days
      })
    ]
  })
);

// 3. Dynamic API fallback: Stale-while-revalidate for read requests
registerRoute(
  ({ url }) => url.pathname.startsWith('/rest/v1/'),
  new NetworkFirst({
    cacheName: 'quadrant-api-cache',
    networkTimeoutSeconds: 3,
    plugins: [
      new ExpirationPlugin({
        maxEntries: 50,
        maxAgeSeconds: 24 * 60 * 60
      })
    ]
  })
);

// Immediate activation
self.addEventListener('install', () => {
  self.skipWaiting();
});

self.addEventListener('activate', (event) => {
  event.waitUntil(self.clients.claim());
});
